// Обновлено 2026-10-06 (#6a86f7e16f63, #a5decf4a): закрытие только ✕, без «סגירה והמשך בתפילה»; «נוסח זמני» / «מקור: … · אושר על ידי …».
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { counterLocator, saveProgress, restoreProgress } from '../_helpers/prayer-nav';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

const TEMP_LINE = 'נוסח זמני, עד לאישור הנוסח הסופי.';

async function openInfo(page: Page, key: string, prayerName: string) {
  await page.goto(`/prayer/${key}`);
  await expect(counterLocator(page)).toBeVisible({ timeout: 20_000 });
  const before = await counterLocator(page).innerText();
  // ⓘ в шапке молитвы.
  await page.getByRole('button', { name: 'הסבר על התפילה' }).click();
  const dialog = page.getByRole('dialog');
  await expect(dialog.getByText(`על תפילת ${prayerName}`, { exact: true })).toBeVisible();
  // Короткое объяснение + плашка «💡 טיפ: …».
  await expect(dialog.getByText(/טיפ: \S/)).toBeVisible();
  await expect(dialog.getByRole('button', { name: 'סגירה והמשך בתפילה' })).toHaveCount(0);
  await expect(dialog.getByText('סגירה והמשך בתפילה')).toHaveCount(0);
  return { dialog, before };
}

async function closeAndCheck(page: Page, key: string, before: string) {
  // ✕ — единственное закрытие.
  await page.getByRole('dialog').getByRole('button', { name: 'סגירה', exact: true }).click();
  await expect(page.getByRole('dialog')).toHaveCount(0);
  await expect(page).toHaveURL(new RegExp(`/prayer/${key}$`));
  await expect(counterLocator(page)).toHaveText(before);
}

test.describe('Молитва по шагам', () => {
  test('GP-02 Окно ⓘ «על התפילה» (не утверждено): «על תפילת מנחה», «💡 טיפ», «נוסח זמני…», без «סגירה והמשך בתפילה», ✕ → тот же קטע #6a86f7ff #6a86f7e16f63 @prod-safe @mobile', async ({ page }) => {
    const saved = await saveProgress(page);
    try {
      const { dialog, before } = await openInfo(page, 'mincha_ashkenaz', 'מנחה');
      await expect(dialog.getByText(TEMP_LINE, { exact: true })).toBeVisible();
      await expect(dialog.getByText(/אושר על ידי/)).toHaveCount(0);
      await closeAndCheck(page, 'mincha_ashkenaz', before);
    } finally {
      await restoreProgress(page, saved);
    }
  });

  test('GP-02 Окно ⓘ «על התפילה» (утверждено в админке): «על תפילת ערבית», «מקור: … · אושר על ידי …» вместо «נוסח זמני» #6a86f7e16f63 #a5decf4a @prod-safe @mobile', async ({ page }) => {
    const saved = await saveProgress(page);
    try {
      const { dialog, before } = await openInfo(page, 'arvit_ashkenaz', 'ערבית');
      // На 06.10: «מקור: בדיקת QA · אושר על ידי בודק QA, 6.10.2026» — источник и имя не сверяем дословно (клиент заменит).
      await expect(dialog.getByText(/^מקור: .+אושר על ידי .+\d{1,2}\.\d{1,2}\.\d{4}/)).toBeVisible();
      await expect(dialog.getByText(TEMP_LINE)).toHaveCount(0);
      await closeAndCheck(page, 'arvit_ashkenaz', before);
    } finally {
      await restoreProgress(page, saved);
    }
  });
});
